20: func NewURLHandler(service *service.URLService) *URLHandler {
21: 	router := chi.NewRouter()
22: 	h := &URLHandler{service: service, Router: router}
23: 	router.Post("/", middleware.GzipCompressor(middleware.RequestLogger(h.createURLHandler)))
24: 	router.Post("/api/shorten", middleware.GzipCompressor(middleware.RequestLogger(h.createURLHandlerJSON)))
25: 	router.Get("/{shorted}", middleware.GzipCompressor(middleware.RequestLogger(h.getURLHandler)))
26: 	return h
27: }
