29: func (h *URLHandler) createURLHandler(w http.ResponseWriter, r *http.Request) {
30: 	if r.Method == http.MethodPost {
31: 		body, err := io.ReadAll(r.Body)
32: 		if err != nil {
33: 			http.Error(w, err.Error(), http.StatusBadRequest)
34: 			return
35: 		}
36: 		w.Header().Set("Content-Type", "text/plain")
37: 		shortURL, err := h.service.CreateShortURL(string(body))
38: 		if err != nil {
39: 			http.Error(w, err.Error(), http.StatusBadRequest)
40: 		}
41: 		w.WriteHeader(http.StatusCreated)
42: 		_, err = w.Write([]byte(shortURL))
43: 		if err != nil {
44: 			http.Error(w, err.Error(), http.StatusBadRequest)
45: 		}
46: 	} else {
47: 		w.WriteHeader(http.StatusBadRequest)
48: 	}
49: }
